import json, hashlib, base64, os
base="/home/nilton/Projetos/nilton/NOVOS/platform-install-packages-php83"
src="/home/nilton/Projetos/nilton/NOVOS/kaltura-rigel-18.20.0-source/server-Rigel-18.20.0"
man=json.load(open(f"{base}/patches/php83/held/curly-offsets/manifest.json"))
lab=json.load(open(f"{base}/doc/php83/evidence/curly-offsets/primary-lab.json"))
r2=json.load(open(f"{base}/doc/php83/evidence/compiler-triage/primary-r2.json"))
lab_by={r['path']:r for r in lab['rows']}
r2_by={r['path']:r for r in r2['rows']}
print(f"manifest_files={len(man['files'])} lab_rows={len(lab['rows'])} r2_total={len(r2['rows'])}")
# cohort exactness
mpaths=[f['path'] for f in man['files']]
print("unique_manifest:", len(set(mpaths)), "dupes:", len(mpaths)-len(set(mpaths)))
print("lab_cohort_match:", set(mpaths)==set(lab_by.keys()))
r2match=[p for p in mpaths if p in r2_by]
print("r2_cohort_match43:", len(r2match), set(mpaths)==set(r2match))
fails=[]
ok_orig_src=ok_patch=ok_b64=ok_len=ok_bytes=ok_cmp=ok_tok=0
tot_pairs=tot_changed=0
for f in man['files']:
  p=f['path']; L=lab_by.get(p); R=r2_by.get(p)
  if L is None or R is None:
    fails.append((p,"missing join")); continue
  # original hash vs source file
  sp=os.path.join(src,p)
  try:
    raw=open(sp,'rb').read()
    h=hashlib.sha256(raw).hexdigest()
  except Exception as e:
    fails.append((p,f"source read fail {e}")); continue
  if h!=f['before_sha256']: fails.append((p,f"before!=source {h[:12]}"))
  else: ok_orig_src+=1
  if L['proof']['before_sha256']!=f['before_sha256']: fails.append((p,"lab before mismatch"))
  if R.get('source_sha256')!=f['before_sha256']: fails.append((p,"r2 source mismatch"))
  # patch hash
  pp=os.path.join(base,f['patch'])
  try:
    ph=hashlib.sha256(open(pp,'rb').read()).hexdigest()
  except Exception as e:
    fails.append((p,f"patch read fail {e}")); continue
  if ph!=f['patch_sha256']: fails.append((p,f"patch sha mismatch {ph[:12]}"))
  else: ok_patch+=1
  # base64 candidate
  try:
    cand=base64.b64decode(L['candidate_base64'],validate=True)
  except Exception as e:
    fails.append((p,f"b64 decode {e}")); continue
  ch=hashlib.sha256(cand).hexdigest()
  if ch!=f['after_sha256']: fails.append((p,f"cand sha {ch[:12]} != after {f['after_sha256'][:12]}"))
  else: ok_b64+=1
  if ch!=L['proof']['after_sha256']: fails.append((p,"lab after mismatch"))
  if len(cand)!=len(raw) or f['changed_bytes']!=len(cand):
    # lengths: curly->[ ] is same length expected
    pass
  if len(cand)==len(raw): ok_len+=1
  else: fails.append((p,f"len orig {len(raw)} cand {len(cand)}"))
  # byte diff only {/[ }/]
  diffs=[i for i in range(len(raw)) if raw[i]!=cand[i]]
  if len(diffs)!=f['changed_bytes']: fails.append((p,f"changed_bytes {f['changed_bytes']} != actual diff {len(diffs)}"))
  if len(diffs)!=L['proof']['changed_bytes']: fails.append((p,"lab changed_bytes mismatch"))
  bad=[]
  for i in diffs:
    a,b=chr(raw[i]),chr(cand[i])
    if not ((a=='{' and b=='[') or (a=='}' and b==']')): bad.append((i,a,b))
  if bad: fails.append((p,f"non-curly diffs {bad[:4]}"))
  else: ok_bytes+=1
  # offset pairs consistency
  pairs=L['proof']['offset_pairs']
  if len(pairs)!=f['offset_pairs']: fails.append((p,f"pairs {f['offset_pairs']} != lab {len(pairs)}"))
  # verify each pair offsets point at diff bytes
  for pr in pairs:
    for side in ('open','close'):
      o=pr[side]; off=o['offset']
      exp_before='{' if side=='open' else '}'; exp_after='[' if side=='open' else ']'
      if o['before']!=exp_before or o['after']!=exp_after: fails.append((p,f"pair {side} before/after {o['before']}->{o['after']}"))
      if raw[off:off+1].decode()!=exp_before or cand[off:off+1].decode()!=exp_after: fails.append((p,f"pair {side} offset {off} mismatch"))
  # compile
  oc,cc=L.get('original_compile',{}),L.get('candidate_compile',{})
  if oc.get('exit')==255 and 'curly braces' in (oc.get('stderr','')+oc.get('stdout','')).lower() and cc.get('exit')==0 and 'no syntax errors' in cc.get('stdout','').lower(): ok_cmp+=1
  else: fails.append((p,f"compile orig={oc.get('exit')} cand={cc.get('exit')}"))
  if L['proof'].get('all_other_bytes_tokens_identical') is True: ok_tok+=1
  else: fails.append((p,"tokens_identical not true"))
  tot_pairs+=f['offset_pairs']; tot_changed+=f['changed_bytes']
print(f"orig_vs_source_ok={ok_orig_src}/43 patch_sha_ok={ok_patch}/43 b64_cand_ok={ok_b64}/43 len_equal_ok={ok_len}/43 curly_only_ok={ok_bytes}/43 compile255to0_ok={ok_cmp}/43 tokens_identical_ok={ok_tok}/43")
print(f"sum_offset_pairs={tot_pairs} sum_changed_bytes={tot_changed} manifest_sums pairs={sum(f['offset_pairs'] for f in man['files'])} bytes={sum(f['changed_bytes'] for f in man['files'])}")
print(f"FAILURES={len(fails)}")
for x in fails[:30]: print(" FAIL:",x)
# r2 category check
cats={}
for p in mpaths:
  c=r2_by[p].get('category'); cats[c]=cats.get(c,0)+1
print("r2_categories_for_cohort:",cats)
print("scan_after:",lab.get('scan_after_totals'),"fix_exit:",lab.get('fix_exit'),"scan_before_exit:",lab.get('scan_before_exit'),"scan_after_exit:",lab.get('scan_after_exit'))
PY
echo "EXIT:$?"

