  if L['proof']['before_sha256']!=f['before_sha256']: fails.append((p,"lab before mismatch"))
  if R.get('source_sha256')!=f['before_sha256']: fails.append((p,"r2 source mismatch"))
  # patch hash
  pp=os.path.join(base,f['patch'])
