  else: fails.append((p,"tokens_identical not true"))
  tot_pairs+=f['offset_pairs']; tot_changed+=f['changed_bytes']
print(f"orig_vs_source_ok={ok_orig_src}/43 patch_sha_ok={ok_patch}/43 b64_cand_ok={ok_b64}/43 len_equal_ok={ok_len}/43 curly_only_ok={ok_bytes}/43 compile255to0_ok={ok_cmp}/43 tokens_identical_ok={ok_tok}/43")
print(f"sum_offset_pairs={tot_pairs} sum_changed_bytes={tot_changed} manifest_sums pairs={sum(f['offset_pairs'] for f in man['files'])} bytes={sum(f['changed_bytes'] for f in man['files'])}")
print(f"FAILURES={len(fails)}")
for x in fails[:30]: print(" FAIL:",x)
# r2 category check
cats={}
for p in mpaths:
